UPDATE T_AI_PROMPT
   SET  STATUS      = #{status}
       ,DECIDED_BY  = #{decidedBy}
       ,DECIDED_DAY = NOW()
 WHERE 1=1
   AND VERSION = #{version}

mapper.select:
SELECT L.ID AS CHAT_ID ,L.USER_ID ,L.QUESTION ,L.ANSWER ,L.TOOLS_USED ,L.RATING FROM T_AI_CHAT_LOG L WHERE 1=1 AND L.RATING = 'DOWN'
AND L.FEEDBACK_DAY > TO_TIMESTAMP(#{sinceAt} / 1000.0)
ORDER BY L.ID DESC LIMIT #{limit}
